import { test, expect } from '@playwright/test';

test('uploads two files', async ({ page }) => {
  await page.goto('/upload');
  await page.getByLabel('Attachment').setInputFiles([
    { name: 'a.txt', mimeType: 'text/plain', buffer: Buffer.from('hello') },
    { name: 'b.txt', mimeType: 'text/plain', buffer: Buffer.from('world!') },
  ]);
  await expect(page.getByRole('list', { name: 'Selected files' }).getByRole('listitem'))
    .toHaveText(['a.txt (5 bytes)', 'b.txt (6 bytes)']);
  await page.getByLabel('Attachment').setInputFiles([]);
  await expect(page.getByRole('status')).toHaveText('No file selected');
});
